17	import { regexFlagNames } from './locatorGenerators';
18	import { getByAltTextSelector, getByLabelSelector, getByPlaceholderSelector, getByTestIdSelector, getByTextSelector, getByTitleSelector } from './locatorUtils';
19	import { parseSelector, stringifySelector } from './selectorParser';
20	import { escapeForAttributeSelector, escapeForTextSelector } from './stringUtils';
21	
22	import type { Language } from './locatorGenerators';
23	import type { ParsedSelector, ParsedSelectorPart } from './selectorParser';
24	
25	type Value = string | number | boolean | RegExp | ParsedSelector;
26	
27	// Arguments of a single call, collected until the call is converted into selector parts.
28	type CallArguments = {
29	  method: string;
30	  args: Value[];
31	  options: Map<string, Value>;
32	};
33	
34	type CallHandler = (call: CallArguments, testIdAttributeName: string) => ParsedSelectorPart[];
35	
36	type Token =
37	  | { kind: 'identifier', value: string }
38	  | { kind: 'string', value: string }
39	  | { kind: 'regex', value: RegExp }
40	  | { kind: 'number', value: number }
41	  | { kind: 'punctuation', value: string }
42	  | { kind: 'end' };
43	
44	type ParserOptions = {
45	  methods: Map<string, CallHandler>;
46	  quotes: string;
47	  rawStrings?: boolean;
48	  regexLiterals?: boolean;
49	  booleans?: [string, string];
50	};
51	
52	const kEscapes = new Map([['n', '\n'], ['r', '\r'], ['t', '\t'], ['b', '\b'], ['f', '\f']]);
53	const kIdentifierRegex = /[A-Za-z_$][\w$]*/y;
54	const kNumberRegex = /-?\d+(\.\d+)?/y;
55	const kRegexFlagsRegex = /[a-z]*/y;
56	
57	function tokenize(source: string, options: ParserOptions): Token[] {
58	  const tokens: Token[] = [];
59	  let pos = 0;
60	
61	  const match = (re: RegExp) => {
62	    re.lastIndex = pos;
63	    const result = re.exec(source)?.[0];
64	    if (result)
65	      pos += result.length;
66	    return result;
67	  };
68	
69	  // In raw strings, backslash only escapes the closing quote and is preserved otherwise.
70	  const readString = (quote: string, raw: boolean) => {
71	    let text = '';
72	    ++pos;
73	    while (pos < source.length && source[pos] !== quote) {
74	      if (source[pos] !== '\\') {
75	        text += source[pos++];
76	        continue;
77	      }
78	      const next = source[pos + 1] ?? '';
79	      pos += 2;
80	      if (raw) {
81	        text += next === quote ? next : '\\' + next;
82	      } else if (next === 'u') {
83	        text += String.fromCharCode(parseInt(source.substring(pos, pos + 4), 16));
84	        pos += 4;
85	      } else {
86	        text += kEscapes.get(next) ?? next;
87	      }
88	    }
89	    if (pos >= source.length)
90	      throw new Error(`Unterminated string in ${source}`);
91	    ++pos;
92	    return text;
93	  };
94	
95	  while (pos < source.length) {
96	    const char = source[pos];
97	    let text: string | undefined;
98	    if (/\s/.test(char)) {
99	      ++pos;
100	    } else if (options.quotes.includes(char)) {
101	      tokens.push({ kind: 'string', value: readString(char, false) });
102	    } else if (options.rawStrings && char === 'r' && options.quotes.includes(source[pos + 1])) {
103	      tokens.push({ kind: 'string', value: readString(source[++pos], true) });
104	    } else if (options.regexLiterals && char === '/') {
105	      const regexSource = readString('/', true);
106	      tokens.push({ kind: 'regex', value: new RegExp(regexSource, match(kRegexFlagsRegex)) });
107	    } else if ('(){}.,:=|'.includes(char)) {
108	      tokens.push({ kind: 'punctuation', value: char });
109	      ++pos;
110	    } else if ((text = match(kIdentifierRegex))) {
111	      tokens.push({ kind: 'identifier', value: text });
112	    } else if ((text = match(kNumberRegex))) {
113	      tokens.push({ kind: 'number', value: +text });
114	    } else {
115	      throw new Error(`Unexpected character "${char}" in ${source}`);
116	    }
117	  }
118	  tokens.push({ kind: 'end' });
119	  return tokens;
120	}
121	
122	function isToken(token: Token, kind: 'identifier' | 'punctuation', value: string): boolean {
123	  return token.kind === kind && token.value === value;
124	}
125	
126	abstract class LocatorParser {
127	  private _tokens: Token[];
128	  private _pos = 0;
129	  private _methods: Map<string, CallHandler>;
130	  private _booleans: [string, string];
131	  private _testIdAttributeName: string;
132	
133	  constructor(source: string, options: ParserOptions, testIdAttributeName: string) {
134	    this._tokens = tokenize(source, options);
135	    this._methods = options.methods;
136	    this._booleans = options.booleans ?? ['true', 'false'];
137	    this._testIdAttributeName = testIdAttributeName;
138	  }
139	
140	  parse(): ParsedSelector {
141	    const selector = this.parseLocator();
142	    if (this.peek().kind !== 'end')
143	      this.unexpected();
144	    // Same as in parseSelector(), nested selectors like internal:chain cannot be first.
145	    if (selector.parts.length && isNestedSelectorPart(selector.parts[0]))
146	      throw new Error(`"${selector.parts[0].name}" selector cannot be first`);
147	    return selector;
148	  }
149	
150	  // Parses a single argument that is either a positional value or an options bag.
151	  protected abstract parseArgument(call: CallArguments): void;
152	
153	  // Parses a language-specific regular expression, e.g. `re.compile(...)`.
154	  protected abstract parseRegex(): RegExp | undefined;
155	
156	  protected parseLocator(): ParsedSelector {
157	    const parts: ParsedSelectorPart[] = [];
158	    // FrameLocator enters the frame lazily, so that first(), last() and nth() apply to the frame element.
159	    let inFrameLocator = false;
160	    do {
161	      const { handler, call } = this.parseCall();
162	      if (inFrameLocator && !kFrameElementHandlers.has(handler)) {
163	        parts.push(selectorPart('internal:control', 'enter-frame'));
164	        inFrameLocator = false;
165	      }
166	      parts.push(...handler(call, this._testIdAttributeName));
167	      if (handler === contentFrameParts || (handler === frameLocatorParts && call.args.length))
168	        inFrameLocator = true;
169	    } while (this.eat('.'));
170	    if (inFrameLocator)
171	      parts.push(selectorPart('internal:control', 'enter-frame'));
172	    return { parts };
173	  }
174	
175	  private parseCall(): { handler: CallHandler, call: CallArguments } {
176	    const method = this.expectIdentifier();
177	    const handler = this._methods.get(method);
178	    if (!handler)
179	      throw new Error(`Unsupported locator method ${method}`);
180	    const call: CallArguments = { method, args: [], options: new Map() };
181	    if (this.eat('(') && !this.eat(')')) {
182	      do
183	        this.parseArgument(call);
184	      while (this.eat(','));
185	      this.expect(')');
186	    }
187	    return { handler, call };
188	  }
189	
190	  protected parseValue(): Value {
191	    const token = this.peek();
192	    if (token.kind === 'string' || token.kind === 'number' || token.kind === 'regex') {
193	      this.next();
194	      return token.value;
195	    }
196	    if (token.kind !== 'identifier')
197	      this.unexpected();
198	    const [trueLiteral, falseLiteral] = this._booleans;
199	    if (this.eatIdentifier(trueLiteral))
200	      return true;
201	    if (this.eatIdentifier(falseLiteral))
202	      return false;
203	    // Java and C# roles, e.g. `AriaRole.BUTTON`.
204	    if (this.eatIdentifier('AriaRole')) {
205	      this.expect('.');
206	      return this.expectIdentifier().toLowerCase();
207	    }
208	    return this.parseRegex() ?? this.parseLocator();
209	  }
210	
211	  // Parses `{ name <separator> value, ... }` after the opening brace.
212	  protected parseOptionsBag(call: CallArguments, separator: string, optionName: (identifier: string) => string) {
213	    while (!this.eat('}')) {
214	      const name = optionName(this.expectIdentifier());
215	      this.expect(separator);
216	      call.options.set(name, this.parseValue());
217	      if (!this.eat(',')) {
218	        this.expect('}');
219	        break;
220	      }
221	    }
222	  }
223	
224	  // Parses `(source[, <flagsEnum>.<flag> ( "|" <flagsEnum>.<flag> )*])`.
225	  protected parseRegexArguments(flagsEnum: string, flagNames: Record<string, string>): RegExp {
226	    this.expect('(');
227	    const source = this.expectString();
228	    let flags = '';
229	    if (this.eat(',')) {
230	      do {
231	        this.expectIdentifier(flagsEnum);
232	        this.expect('.');
233	        const name = this.expectIdentifier();
234	        const flag = Object.keys(flagNames).find(flag => flagNames[flag] === name);
235	        if (!flag)
236	          throw new Error(`Unsupported regular expression flag ${flagsEnum}.${name}`);
237	        flags += flag;
238	      } while (this.eat('|'));
239	    }
240	    this.expect(')');
241	    return new RegExp(source, flags);
242	  }
243	
244	  protected peek(offset = 0): Token {
245	    return this._tokens[Math.min(this._pos + offset, this._tokens.length - 1)];
246	  }
247	
248	  protected next(): Token {
249	    const token = this.peek();
250	    if (token.kind !== 'end')
251	      ++this._pos;
252	    return token;
253	  }
254	
255	  protected eat(punctuation: string): boolean {
256	    if (!isToken(this.peek(), 'punctuation', punctuation))
257	      return false;
258	    this.next();
259	    return true;
260	  }
261	
262	  protected eatIdentifier(identifier: string): boolean {
263	    if (!isToken(this.peek(), 'identifier', identifier))
264	      return false;
265	    this.next();
266	    return true;
267	  }
268	
269	  protected expect(punctuation: string) {
270	    if (!this.eat(punctuation))
271	      this.unexpected();
272	  }
273	
274	  protected expectIdentifier(identifier?: string): string {
275	    const token = this.peek();
276	    if (token.kind !== 'identifier' || (identifier !== undefined && token.value !== identifier))
277	      this.unexpected();
278	    this.next();
279	    return token.value;
280	  }
281	
282	  protected expectString(): string {
283	    const token = this.next();
284	    if (token.kind !== 'string')
285	      this.unexpected();
286	    return token.value;
287	  }
288	
289	  protected unexpected(): never {
290	    const token = this.peek();
291	    throw new Error(`Unexpected ${token.kind === 'end' ? 'end of input' : `token "${token.value}"`}`);
292	  }
293	}
