295	// getByRole('button', { name: /submit/i, exact: true })
296	class JavaScriptLocatorParser extends LocatorParser {
297	  constructor(source: string, testIdAttributeName: string) {
298	    super(source, { methods: kJavaScriptMethods, quotes: '\'"`', regexLiterals: true }, testIdAttributeName);
299	  }
300	
301	  protected parseArgument(call: CallArguments) {
302	    if (this.eat('{'))
303	      this.parseOptionsBag(call, ':', name => name);
304	    else
305	      call.args.push(this.parseValue());
306	  }
307	
308	  // Regular expression literals are tokens.
309	  protected parseRegex(): RegExp | undefined {
310	    return undefined;
311	  }
312	}
313	
314	// get_by_role("button", name=re.compile(r"submit", re.IGNORECASE), exact=True)
315	class PythonLocatorParser extends LocatorParser {
316	  constructor(source: string, testIdAttributeName: string) {
317	    super(source, { methods: kPythonMethods, quotes: '\'"', rawStrings: true, booleans: ['True', 'False'] }, testIdAttributeName);
318	  }
319	
320	  protected parseArgument(call: CallArguments) {
321	    if (!isToken(this.peek(1), 'punctuation', '=')) {
322	      call.args.push(this.parseValue());
323	      return;
324	    }
325	    const name = this.expectIdentifier();
326	    this.expect('=');
327	    call.options.set(name.replace(/_([a-z])/g, (_, char) => char.toUpperCase()), this.parseValue());
328	  }
329	
330	  protected parseRegex(): RegExp | undefined {
331	    if (!this.eatIdentifier('re'))
332	      return;
333	    this.expect('.');
334	    this.expectIdentifier('compile');
335	    return this.parseRegexArguments('re', regexFlagNames.python);
336	  }
337	}
338	
339	// getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName(Pattern.compile("submit", Pattern.CASE_INSENSITIVE)).setExact(true))
340	class JavaLocatorParser extends LocatorParser {
341	  constructor(source: string, testIdAttributeName: string) {
342	    super(source, { methods: kJavaScriptMethods, quotes: '"' }, testIdAttributeName);
343	  }
344	
345	  protected parseArgument(call: CallArguments) {
346	    if (!this.eatIdentifier('new')) {
347	      call.args.push(this.parseValue());
348	      return;
349	    }
350	    // Options class, e.g. `Locator.FilterOptions`.
351	    this.expectIdentifier();
352	    this.expect('.');
353	    this.expectIdentifier();
354	    this.expect('(');
355	    this.expect(')');
356	    while (this.eat('.')) {
357	      const setter = this.expectIdentifier();
358	      if (!setter.startsWith('set'))
359	        throw new Error(`Unexpected options method ${setter}`);
360	      this.expect('(');
361	      call.options.set(lowerFirst(setter.substring('set'.length)), this.parseValue());
362	      this.expect(')');
363	    }
364	  }
365	
366	  protected parseRegex(): RegExp | undefined {
367	    if (!this.eatIdentifier('Pattern'))
368	      return;
369	    this.expect('.');
370	    this.expectIdentifier('compile');
371	    return this.parseRegexArguments('Pattern', regexFlagNames.java);
372	  }
373	}
374	
375	// GetByRole(AriaRole.Button, new() { NameRegex = new Regex("submit", RegexOptions.IgnoreCase), Exact = true })
376	class CSharpLocatorParser extends LocatorParser {
377	  constructor(source: string, testIdAttributeName: string) {
378	    super(source, { methods: kCSharpMethods, quotes: '"' }, testIdAttributeName);
379	  }
380	
381	  protected parseArgument(call: CallArguments) {
382	    // `new() { ... }` is an options bag, while `new Regex(...)` is a value.
383	    if (!isToken(this.peek(), 'identifier', 'new') || !isToken(this.peek(1), 'punctuation', '(')) {
384	      call.args.push(this.parseValue());
385	      return;
386	    }
387	    this.next();
388	    this.expect('(');
389	    this.expect(')');
390	    this.expect('{');
391	    // Regular expression options have a "Regex" suffix, e.g. `NameRegex`.
392	    this.parseOptionsBag(call, '=', name => lowerFirst(name.replace(/Regex$/, '')));
393	  }
394	
395	  protected parseRegex(): RegExp | undefined {
396	    if (!this.eatIdentifier('new'))
397	      return;
398	    this.expectIdentifier('Regex');
399	    return this.parseRegexArguments('RegexOptions', regexFlagNames.csharp);
400	  }
401	}
402	
403	const parsers: Partial<Record<Language, new (source: string, testIdAttributeName: string) => LocatorParser>> = {
404	  javascript: JavaScriptLocatorParser,
405	  python: PythonLocatorParser,
406	  java: JavaLocatorParser,
407	  csharp: CSharpLocatorParser,
408	};
409	
410	const kFilterOptions = ['hasText', 'hasNotText', 'has', 'hasNot', 'visible'];
411	
412	function locatorParts(call: CallArguments): ParsedSelectorPart[] {
413	  checkArguments(call, 1, kFilterOptions);
414	  const inner = arg(call, 0, (value): value is string | ParsedSelector => isString(value) || isSelector(value));
415	  const parts = isString(inner) ? parseSelector(inner).parts : [nestedSelectorPart('internal:chain', inner)];
416	  return [...parts, ...filterSelectorParts(call)];
417	}
418	
419	function filterParts(call: CallArguments): ParsedSelectorPart[] {
420	  checkArguments(call, 0, kFilterOptions);
421	  return filterSelectorParts(call);
422	}
423	
424	function nestedParts(name: string): CallHandler {
425	  return call => {
426	    checkArguments(call, 1, []);
427	    return [nestedSelectorPart(name, arg(call, 0, isSelector))];
428	  };
429	}
430	
431	function frameLocatorParts(call: CallArguments): ParsedSelectorPart[] {
432	  checkArguments(call, 1, []);
433	  return call.args.length ? parseSelector(arg(call, 0, isString)).parts : [selectorPart('internal:control', 'any-frame')];
434	}
435	
436	// Entering the frame is deferred by the parser.
437	function contentFrameParts(call: CallArguments): ParsedSelectorPart[] {
438	  checkArguments(call, 0, []);
439	  return [];
440	}
441	
442	function fixedNthParts(index: string): CallHandler {
443	  return call => {
444	    checkArguments(call, 0, []);
445	    return [selectorPart('nth', index)];
446	  };
447	}
448	
449	function nthParts(call: CallArguments): ParsedSelectorPart[] {
450	  checkArguments(call, 1, []);
451	  return [selectorPart('nth', String(arg(call, 0, isNumber)))];
452	}
453	
454	function visibleParts(call: CallArguments): ParsedSelectorPart[] {
455	  checkArguments(call, 0, []);
456	  return [selectorPart('visible', 'true')];
457	}
458	
459	function getByTestIdParts(call: CallArguments, testIdAttributeName: string): ParsedSelectorPart[] {
460	  checkArguments(call, 1, []);
461	  return parseSelector(getByTestIdSelector(testIdAttributeName, arg(call, 0, isText))).parts;
462	}
463	
464	function textParts(toSelector: (text: string | RegExp, options: { exact?: boolean }) => string): CallHandler {
465	  return call => {
466	    checkArguments(call, 1, ['exact']);
467	    return parseSelector(toSelector(arg(call, 0, isText), { exact: option(call, 'exact', isBoolean) })).parts;
468	  };
469	}
470	
471	const andParts = nestedParts('internal:and');
472	const orParts = nestedParts('internal:or');
473	const firstParts = fixedNthParts('0');
474	const lastParts = fixedNthParts('-1');
475	const getByTextParts = textParts(getByTextSelector);
476	const getByLabelParts = textParts(getByLabelSelector);
477	const getByAltTextParts = textParts(getByAltTextSelector);
478	const getByPlaceholderParts = textParts(getByPlaceholderSelector);
479	const getByTitleParts = textParts(getByTitleSelector);
480	
481	const kFrameElementHandlers = new Set<CallHandler>([firstParts, lastParts, nthParts]);
482	
483	// JavaScript and Java share the method names.
484	const kJavaScriptMethods = new Map<string, CallHandler>([
485	  ['locator', locatorParts],
486	  ['filter', filterParts],
487	  ['and', andParts],
488	  ['or', orParts],
489	  ['frameLocator', frameLocatorParts],
490	  ['contentFrame', contentFrameParts],
491	  ['first', firstParts],
492	  ['last', lastParts],
493	  ['nth', nthParts],
494	  ['visible', visibleParts],
495	  ['getByRole', getByRoleParts],
496	  ['getByText', getByTextParts],
497	  ['getByLabel', getByLabelParts],
498	  ['getByTestId', getByTestIdParts],
499	  ['getByAltText', getByAltTextParts],
500	  ['getByPlaceholder', getByPlaceholderParts],
501	  ['getByTitle', getByTitleParts],
502	]);
503	
504	const kPythonMethods = new Map<string, CallHandler>([
505	  ['locator', locatorParts],
506	  ['filter', filterParts],
507	  ['and_', andParts],
508	  ['or_', orParts],
509	  ['frame_locator', frameLocatorParts],
510	  ['content_frame', contentFrameParts],
511	  ['first', firstParts],
512	  ['last', lastParts],
513	  ['nth', nthParts],
514	  ['visible', visibleParts],
515	  ['get_by_role', getByRoleParts],
516	  ['get_by_text', getByTextParts],
517	  ['get_by_label', getByLabelParts],
518	  ['get_by_test_id', getByTestIdParts],
519	  ['get_by_alt_text', getByAltTextParts],
520	  ['get_by_placeholder', getByPlaceholderParts],
521	  ['get_by_title', getByTitleParts],
522	]);
523	
524	const kCSharpMethods = new Map<string, CallHandler>([
525	  ['Locator', locatorParts],
526	  ['Filter', filterParts],
527	  ['And', andParts],
528	  ['Or', orParts],
529	  ['FrameLocator', frameLocatorParts],
530	  ['ContentFrame', contentFrameParts],
531	  ['First', firstParts],
532	  ['Last', lastParts],
533	  ['Nth', nthParts],
534	  ['Visible', visibleParts],
535	  ['GetByRole', getByRoleParts],
536	  ['GetByText', getByTextParts],
537	  ['GetByLabel', getByLabelParts],
538	  ['GetByTestId', getByTestIdParts],
539	  ['GetByAltText', getByAltTextParts],
540	  ['GetByPlaceholder', getByPlaceholderParts],
541	  ['GetByTitle', getByTitleParts],
542	]);
543	
544	function filterSelectorParts(call: CallArguments): ParsedSelectorPart[] {
545	  const parts: ParsedSelectorPart[] = [];
546	  const hasText = option(call, 'hasText', isText);
547	  if (hasText !== undefined)
548	    parts.push(selectorPart('internal:has-text', escapeForTextSelector(hasText, false)));
549	  const hasNotText = option(call, 'hasNotText', isText);
550	  if (hasNotText !== undefined)
551	    parts.push(selectorPart('internal:has-not-text', escapeForTextSelector(hasNotText, false)));
552	  const has = option(call, 'has', isSelector);
553	  if (has)
554	    parts.push(nestedSelectorPart('internal:has', has));
555	  const hasNot = option(call, 'hasNot', isSelector);
556	  if (hasNot)
557	    parts.push(nestedSelectorPart('internal:has-not', hasNot));
558	  const visible = option(call, 'visible', isBoolean);
559	  if (visible !== undefined)
560	    parts.push(selectorPart('visible', String(visible)));
561	  return parts;
562	}
563	
564	function getByRoleParts(call: CallArguments): ParsedSelectorPart[] {
565	  checkArguments(call, 1, ['name', 'description', 'exact', 'checked', 'disabled', 'expanded', 'includeHidden', 'level', 'pressed', 'selected']);
566	  const exact = !!option(call, 'exact', isBoolean);
567	  let body = arg(call, 0, isString);
568	  for (const name of call.options.keys()) {
569	    if (name === 'name' || name === 'description')
570	      body += `[${name}=${escapeForAttributeSelector(option(call, name, isText)!, exact)}]`;
571	    else if (name === 'level')
572	      body += `[level=${option(call, name, isNumber)}]`;
573	    else if (name !== 'exact')
574	      body += `[${name === 'includeHidden' ? 'include-hidden' : name}=${option(call, name, isBoolean)}]`;
575	  }
576	  return [selectorPart('internal:role', body)];
577	}
578	
579	function selectorPart(name: string, body: string): ParsedSelectorPart {
580	  return { name, body, source: body };
581	}
582	
583	function nestedSelectorPart(name: string, parsed: ParsedSelector): ParsedSelectorPart {
584	  return { name, body: { parsed }, source: JSON.stringify(stringifySelector(parsed)) };
585	}
586	
587	function isNestedSelectorPart(part: ParsedSelectorPart): boolean {
588	  return typeof part.body === 'object' && 'parsed' in part.body;
589	}
590	
591	function checkArguments(call: CallArguments, maxArgs: number, allowedOptions: string[]) {
592	  if (call.args.length > maxArgs)
593	    throw new Error(`Too many arguments for ${call.method}`);
594	  for (const name of call.options.keys()) {
595	    if (!allowedOptions.includes(name))
596	      throw new Error(`Unsupported option ${name} for ${call.method}`);
597	  }
598	}
