600	function arg<T extends Value>(call: CallArguments, index: number, is: (value: Value) => value is T): T {
601	  const value = call.args[index];
602	  if (value === undefined || !is(value))
603	    throw new Error(`Unexpected argument #${index} for ${call.method}`);
604	  return value;
605	}
606	
607	function option<T extends Value>(call: CallArguments, name: string, is: (value: Value) => value is T): T | undefined {
608	  const value = call.options.get(name);
609	  if (value !== undefined && !is(value))
610	    throw new Error(`Unexpected ${name} option for ${call.method}`);
611	  return value;
612	}
613	
614	function isString(value: Value): value is string {
615	  return typeof value === 'string';
616	}
617	
618	function isText(value: Value): value is string | RegExp {
619	  return typeof value === 'string' || value instanceof RegExp;
620	}
621	
622	function isNumber(value: Value): value is number {
623	  return typeof value === 'number';
624	}
625	
626	function isBoolean(value: Value): value is boolean {
627	  return typeof value === 'boolean';
628	}
629	
630	function isSelector(value: Value): value is ParsedSelector {
631	  return typeof value === 'object' && !(value instanceof RegExp);
632	}
633	
634	function lowerFirst(identifier: string): string {
635	  return identifier.charAt(0).toLowerCase() + identifier.substring(1);
636	}
637	
638	export function locatorOrSelectorAsSelector(language: Language, locator: string, testIdAttributeName: string = 'data-testid'): string {
639	  try {
640	    return unsafeLocatorOrSelectorAsSelector(language, locator, testIdAttributeName);
641	  } catch (e) {
642	    return '';
643	  }
644	}
645	
646	export function unsafeLocatorOrSelectorAsSelector(language: Language, locator: string, testIdAttributeName: string = 'data-testid'): string {
647	  try {
648	    parseSelector(locator);
649	    return locator;
650	  } catch (e) {
651	  }
652	  const Parser = parsers[language];
653	  if (!Parser)
654	    return '';
655	  return stringifySelector(new Parser(locator, testIdAttributeName).parse());
656	}
