  | { kind: 'regex', value: RegExp }
  | { kind: 'number', value: number }
  | { kind: 'punctuation', value: string }
  | { kind: 'end' };

type ParserOptions = {
  methods: Map<string, CallHandler>;
  quotes: string;
  rawStrings?: boolean;
  regexLiterals?: boolean;
  booleans?: [string, string];
};

