  protected parseArgument(call: CallArguments) {
    // `new() { ... }` is an options bag, while `new Regex(...)` is a value.
    if (!isToken(this.peek(), 'identifier', 'new') || !isToken(this.peek(1), 'punctuation', '(')) {
      call.args.push(this.parseValue());
      return;
    }
    this.next();
    this.expect('(');
    this.expect(')');
    this.expect('{');
